window.ScripturaLexicons.BDAG_PART_0289 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-01\" data-source=\"BDAG\" data-search=\"πληγή, ῆς, ἡ substantivo feminino golpe; ferida; praga BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πληγή, ῆς, ἡ</td><td>substantivo feminino</td><td>golpe; ferida; praga</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-02\" data-source=\"BDAG\" data-search=\"πλῆθος, ους, τό substantivo neutro quantidade; multidão; comunidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλῆθος, ους, τό</td><td>substantivo neutro</td><td>quantidade; multidão; comunidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-03\" data-source=\"BDAG\" data-search=\"πληθύνω verbo multiplicar; aumentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πληθύνω</td><td>verbo</td><td>multiplicar; aumentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-04\" data-source=\"BDAG\" data-search=\"πλήκτης, ου, ὁ substantivo masculino valentão; briguento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλήκτης, ου, ὁ</td><td>substantivo masculino</td><td>valentão; briguento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-05\" data-source=\"BDAG\" data-search=\"πλημμέλεια, ας, ἡ substantivo feminino falta; erro; transgressão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλημμέλεια, ας, ἡ</td><td>substantivo feminino</td><td>falta; erro; transgressão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-06\" data-source=\"BDAG\" data-search=\"πλήμμυρα, ης substantivo feminino cheia; inundação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλήμμυρα, ης</td><td>substantivo feminino</td><td>cheia; inundação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-07\" data-source=\"BDAG\" data-search=\"πλήν partícula; advérbio; preposição contudo; porém; exceto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλήν</td><td>partícula; advérbio; preposição</td><td>contudo; porém; exceto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-08\" data-source=\"BDAG\" data-search=\"πλήρης, ες adjetivo cheio; pleno; completo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλήρης, ες</td><td>adjetivo</td><td>cheio; pleno; completo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-09\" data-source=\"BDAG\" data-search=\"πληροφορέω verbo cumprir plenamente; persuadir inteiramente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πληροφορέω</td><td>verbo</td><td>cumprir plenamente; persuadir inteiramente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-10\" data-source=\"BDAG\" data-search=\"πληροφορία, ας, ἡ substantivo feminino plena convicção; certeza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πληροφορία, ας, ἡ</td><td>substantivo feminino</td><td>plena convicção; certeza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-11\" data-source=\"BDAG\" data-search=\"πληρόω verbo encher; completar; cumprir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πληρόω</td><td>verbo</td><td>encher; completar; cumprir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-12\" data-source=\"BDAG\" data-search=\"πλήρωμα, ατος, τό substantivo neutro plenitude; complemento; cumprimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλήρωμα, ατος, τό</td><td>substantivo neutro</td><td>plenitude; complemento; cumprimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-13\" data-source=\"BDAG\" data-search=\"πλήσας, πλησθείς, πλησθῆναι remissão gramatical ver πίμπλημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλήσας, πλησθείς, πλησθῆναι</td><td>remissão gramatical</td><td>ver πίμπλημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-14\" data-source=\"BDAG\" data-search=\"πλησίον advérbio; substantivo perto; próximo; semelhante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλησίον</td><td>advérbio; substantivo</td><td>perto; próximo; semelhante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-15\" data-source=\"BDAG\" data-search=\"πλησμονή, ῆς, ἡ substantivo feminino saciedade; satisfação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλησμονή, ῆς, ἡ</td><td>substantivo feminino</td><td>saciedade; satisfação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-16\" data-source=\"BDAG\" data-search=\"πλήσσω verbo golpear; atingir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλήσσω</td><td>verbo</td><td>golpear; atingir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-17\" data-source=\"BDAG\" data-search=\"πλοιάριον, ου, τό substantivo neutro barquinho; barco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλοιάριον, ου, τό</td><td>substantivo neutro</td><td>barquinho; barco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-18\" data-source=\"BDAG\" data-search=\"πλοῖον, ου, τό substantivo neutro navio; barco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλοῖον, ου, τό</td><td>substantivo neutro</td><td>navio; barco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-19\" data-source=\"BDAG\" data-search=\"πλόκαμος, ου, ὁ substantivo masculino trança; mecha de cabelo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλόκαμος, ου, ὁ</td><td>substantivo masculino</td><td>trança; mecha de cabelo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0289-20\" data-source=\"BDAG\" data-search=\"πλοκή, ῆς, ἡ substantivo feminino trançado; trança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλοκή, ῆς, ἡ</td><td>substantivo feminino</td><td>trançado; trança</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0289-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πληγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πληγή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πλήσσω</span>; Hom.+; inscrições, papiros, LXX; En, TestJob, Test12Patr; JosAs 17:3 cód. A [p. 66, 4 Bat.]; ApcMos 8; Just., D. 132, 2 [«praga» de camundongos, ver 1 Km 6]; Mel., P. 18, 120; 87, 657), «golpe».</p><p class=\"entry-text\">① Golpe repentino e forte produzido por algum instrumento; golpe, pancada, literalmente (Diod S 4, 43, 3 [golpe de chicote]; Jos., Vi. 335): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:48</a> (sobre a omissão de <span class=\"greek\">πληγάς</span> com <span class=\"greek\">πολλάς</span>, <span class=\"greek\">ὀλίγας</span> nos vv. 47s., ver <span class=\"greek\">δέρω</span> e cf. Pla., Leg. 9, 854d; 879e; Demosth. 19, 197; Herodas 3, 77; 5, 33; Diod S 36, 8, 3 <span class=\"greek\">τρίτην</span> [isto é, <span class=\"greek\">πληγὴν</span>] <span class=\"greek\">λαβών</span>; B-D-F §241, 6; Rob. 653); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:5</a>; 11:23. <span class=\"greek\">ἐπιθεῖναί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">πληγάς</span>, «aplicar golpes a alguém» (<span class=\"greek\">ἐπιτίθημι</span> 1a<span class=\"greek\">β</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:23</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:30</a>.</p><p class=\"entry-text\">② Ferimento produzido por um golpe; ferida, contusão (Diod S 15, 55, 4; Nicol. Dam.: 90 Fgm. 130, 26 p. 410, 24 Jac.; Appian, Iber. 74 §314 e outros; escólio a Pla., Rep. 566a; Jos., Ant. 7, 128; 10, 77), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:33</a> (Appian, Bell. Civ. 2, 26 §98 <span class=\"greek\">πλ</span>. = vergão, cicatriz causada por golpes de varas). <span class=\"greek\">ἡ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">μαχαίρης</span>, «ferida de espada» (cf. Philosoph. Max. 496, 151 <span class=\"greek\">ξίφους</span> <span class=\"greek\">πληγή</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:14</a> (<span class=\"greek\">πλ</span>. isoladamente = ferida mortal: Diod S 16, 12, 3; Jos., Ant. 9, 121.—<span class=\"greek\">πλ</span>. <span class=\"greek\">ἔχειν</span>: Anaxandrides Com. 72). <span class=\"greek\">ἡ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span>, «ferida mortal» (cf. Lucian, Dial. Deor. 14, 2; Plut., Anton. 951 [76, 10] <span class=\"greek\">πλ</span>. <span class=\"greek\">εὐθυθάνατος</span>), vv. 3, 12. O singular coletivo <span class=\"greek\">ἡ</span> <span class=\"greek\">πληγή</span>, «ferimento» = «feridas», B 5:12; B 7:2.</p><p class=\"entry-text\">③ Calamidade repentina que causa intenso sofrimento; golpe no sentido de «golpe do destino» etc. (Aeschyl. e outros; Polyb. 14, 9, 6; Appian, Bell. Civ. 3, 72 §295; LXX; En 10:7; TestJob 4:4 e outros; Philo, Joseph.), extensão figurada de 1 e 2: praga, desgraça (enviada por Deus: <span class=\"greek\">Διὸς</span> <span class=\"greek\">πλ</span>., Aeschyl., Ag. 367; Soph., Aj. 137. <span class=\"greek\">πληγαὶ</span> <span class=\"greek\">θεοῦ</span>, Plut., Mor. 168c.—Ex 11:1 e frequentemente; Test12Patr; ApcMos 8; Jos., Bell. 1, 373, Ant. 6, 94; SibOr 3, 306; 519; Mel., P. 87, 657 <span class=\"greek\">τὰς</span> <span class=\"greek\">δέκα</span> <span class=\"greek\">πλ</span>.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:18</a>, 20; 11:6; 15:1, 6, 8; 16:9, 21ab; 18:4, 8; 21:9; 22:18. A respeito do Servo sofredor de Deus: <span class=\"greek\">ἐν</span> <span class=\"greek\">πληγῇ</span> <span class=\"greek\">εἶναι</span>, «ser atingido pela desgraça», 1 Cl 16:3, 4 (Is 53:3, 4; TestJob 27:5; cf. 2 <span class=\"greek\">ἐν</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">ὑπάρχεις</span> e 35:1); <span class=\"greek\">καθαρίσαι</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πλ</span>., «livrá-lo da desgraça», v. 10 (Is 53:10).—B. 305. DELG s.v. <span class=\"greek\">πλήσσω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλῆθος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλῆθος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πίμπλημι</span>; Hom.+.—Em nossa literatura, falta em Mt, nas epístolas paulinas, nas epístolas católicas [exceto Js e 1 Pt], em Rv e D [B só o apresenta em citação do AT]; no NT a grande maioria das ocorrências está em Lk e Ac).</p><p class=\"entry-text\">① Fato ou condição de serem muitos; quantidade/número: <span class=\"greek\">καθὼς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄστρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πλήθει</span>, «quanto ao número, como as estrelas do céu», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:12</a> (cf. Josh 11:4; Da 3:36 leitura variante; TestJob 13:2.—Ver também Hdt. 6, 44 e outros).</p><p class=\"entry-text\">② Grande quantidade, grande número, multidão, em sentido concreto.</p><p class=\"entry-text\">ⓐ De coisas, com genitivo (Diod S 15, 3, 3 <span class=\"greek\">σίτου</span>; 15, 9, 3; Polyaenus 8, 28, Exc. 15, 9; TestJob 18:4 <span class=\"greek\">τῶν</span> <span class=\"greek\">ὠδίνων</span>; JosAs 5:7 <span class=\"greek\">καρποῦ</span>; SEG VIII, 467, 15s. [217 a.C.] <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">χρυσίου</span> <span class=\"greek\">κτλ</span>.): <span class=\"greek\">πλ</span>. <span class=\"greek\">ἰχθύων</span> (Eparchides [séc. III a.C.]: 437 Fgm. 1 Jac.; Diod S 3, 44, 8; 5, 19, 4) <span class=\"greek\">πολύ</span>, «grande quantidade de peixes», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:6</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:6</a>. <span class=\"greek\">πλ</span>. <span class=\"greek\">ἁμαρτιῶν</span>, «multidão de pecados» (cf. Sir 5:6; Ezk 28:17s.; ParJer 1:1, 8; Jos., Ant. 12, 167), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:8</a>; 1 Cl 49:5; 2 Cl 16:4. <span class=\"greek\">φρυγάνων</span> <span class=\"greek\">πλ</span>., «feixe de gravetos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:3</a>. <span class=\"greek\">πλ</span>. <span class=\"greek\">αἵματος</span>, «grande quantidade de sangue», MPol 16:1. <span class=\"greek\">πλ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">χαλάζης</span>, «densidade da chuva de granizo», AcPl Ha 5, 10. <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">θυσίων</span>, «multidão de sacrifícios», B 2:5 (Is 1:11). <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">οἰκτιρμῶν</span> <span class=\"greek\">σου</span>, «abundância da tua compaixão», 1 Cl 18:2 (Ps 50:3). <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">σχισμάτων</span>, «grande número de fendas», Hs 9, 8, 3.</p><p class=\"entry-text\">ⓑ De pessoas.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Em geral, aglomeração (de pessoas), multidão, grande ajuntamento; também, especificamente, multidão desorganizada (como Maximus Tyr. 39, 2eh): <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:7</a>s. Com genitivo de pessoas (Diod S 15, 14, 4 <span class=\"greek\">στρατιωτῶν</span>; Cebes 1, 3 <span class=\"greek\">γυναικῶν</span>; Appian, Bell. Civ. 1, 81 §370 <span class=\"greek\">στρατιᾶς</span> <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλ</span>. = grande número de militares; Jos., Bell. 7, 35, Ant. 18, 61; Just., D. 120, 2): <span class=\"greek\">πλῆθος</span> <span class=\"greek\">πολὺ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span>, «grande multidão do povo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:17</a>; 23:27 (uma <span class=\"greek\">πλ</span>. numa execução, Jos., Ant. 19, 270). <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:36</a> (<span class=\"greek\">πλῆθος</span> … <span class=\"greek\">κράζοντες</span> é construção segundo o sentido, como Diod S 13, 111, 1 <span class=\"greek\">συνέδριον</span> … <span class=\"greek\">λέγοντες</span>; Polyb. 18, 9, 9 <span class=\"greek\">σύγκλητος</span> … <span class=\"greek\">ἐκεῖνοι</span> e expressões semelhantes). <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχλου</span>, Hs 9, 4, 4. <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀσθενούντων</span>, «grande número de enfermos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3</a>. <span class=\"greek\">Ἑλλήνων</span> <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:1</a>; 17:4. <span class=\"greek\">πλῆθός</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἀνδρῶν</span>, «grande número de (outros) homens», Hs 9, 3, 1 (Diod S 15, 76, 2 e Appian, Iber. 59 §248 <span class=\"greek\">πλ</span>. <span class=\"greek\">ἀνδρῶν</span>; Bell. Civ. 2, 67 §276 <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">ἀνδρῶν</span>). <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">ἐκλεκτῶν</span>, 1 Cl 6:1.—De anjos: <span class=\"greek\">πλ</span>. <span class=\"greek\">στρατιᾶς</span> <span class=\"greek\">οὐρανίου</span>, «multidão do exército celestial», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:13</a> (<span class=\"greek\">πλ</span>. de militares, Diod S 20, 50, 6; Appian, Bell. Civ. 1, 81 §370 <span class=\"greek\">στρατιᾶς</span> <span class=\"greek\">πλ</span>.; Jos., Ant. 14, 482). <span class=\"greek\">τὸ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγγέλων</span> <span class=\"greek\">αὐτοῦ</span>, 1 Cl 34:5.—Plural (cf. Socrat., Ep. 1, 2; Diod S 1, 64, 5; 1, 85, 2; Appian, Bell. Civ. 2, 120 §503; 2 Macc 12:27; 3 Macc 5:24; EpArist 15; 21; ver Mayser II/1, 1926, 38s.): <span class=\"greek\">πλήθη</span> <span class=\"greek\">ἀνδρῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γυναικῶν</span>, «grandes multidões de homens e mulheres», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:14</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Reunião (determinada), assembleia: <span class=\"greek\">ἐσχίσθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:7</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>., MPol 3:2. <span class=\"greek\">ἅπαν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">αὐτῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:1</a> (o verbo está no plural, como em Polyaenus 7, 1; 8, 46; Xenophon Eph. 1, 3, 1 <span class=\"greek\">ἦλθον</span> <span class=\"greek\">ἅπαν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span>).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Povo, população, habitantes (Diod S 5, 15, 2; Appian, Samn. 4 §14; SIG 581, 95 [cerca de 200 a.C.] <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">Ῥοδίων</span>; 695, 20 [séc. II a.C.] <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">Μαγνήτων</span>; IG XII/1, 846, 10; 847, 14 [cf. SIG 765, 129 nota 5: <span class=\"greek\">τὸ</span> <span class=\"greek\">πλέθος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">Λινδίων</span>]; 1 Macc 8:20; 2 Macc 11:16; EpArist 308, os três últimos: <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span>; Jos., Vi. 198 <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Γαλιλαίων</span>; Just., D. 119, 4 <span class=\"greek\">Ἁμμανιτῶν</span> <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλ</span>.): <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span>, «a população», em emprego absoluto (como Polyaenus 8, 47; 50), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:6</a>; 1 Cl 53:5 (= <span class=\"greek\">ὁ</span> <span class=\"greek\">λαός</span> nos vv. 3, 4). <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:7</a> D; AcPl Ha 4, 21. Com genitivo: <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> (Sir 7:7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:4</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">πέριξ</span> <span class=\"greek\">πόλεων</span>, 5:16. <span class=\"greek\">ἅπαν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">περιχώρου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:37</a>. <span class=\"greek\">ἅπαν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:24</a>; cf. MPol 12:2.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. No uso das comunidades cultuais, termo técnico para o conjunto de seus membros: associação, comunidade, congregação (cf. 1QS 5:2, 9, 22; 6:19; IG XII/1, 155, 6; 156, 5; SIG 1023, 16s. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>[<span class=\"greek\">ῆθος</span>] <span class=\"greek\">τῶν</span> <span class=\"greek\">μετεχόντων</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span>; OGI 56, 71 [237 a.C.]; Lucian, Syr. Dea 50); em emprego absoluto, <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>., «a comunidade, a igreja», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:30</a>; 19:9; 21:22 leitura variante; 1 Cl 54:2; ISm 8:2; Hm 11:9. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>., «toda a comunidade, todo o grupo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:5</a>; 15:12. Também <span class=\"greek\">τὸ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">πλ</span>., IMg 6:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">πλ</span>., ITr 8:2. Com genitivo: <span class=\"greek\">τὸ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">ὑμῶν</span>, 1:1. <span class=\"greek\">πᾶν</span> <span class=\"greek\">το</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:10</a>. <span class=\"greek\">ἅπαν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">μαθητῶν</span>, «toda a comunidade dos discípulos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:37</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:2</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">πιστευσάντων</span>, 4:32.—Dssm., NB 59s. [BS 232s.].—B. 929. DELG s.v. <span class=\"greek\">πίμπλημι</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πληθύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πληθύνω</span> (cf. <span class=\"greek\">πλῆθος</span>); futuro <span class=\"greek\">πληθυνῶ</span>; primeiro aoristo, optativo, terceira pessoa do singular <span class=\"greek\">πληθύναι</span> (Gen 28:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:10</a> t.r.). Passivo: imperfeito <span class=\"greek\">ἐπληθυνόμην</span>; futuro, terceira pessoa do singular <span class=\"greek\">πληθυνθήσεται</span>, terceira do plural <span class=\"greek\">πληθυνθήσονται</span> LXX; primeiro aoristo <span class=\"greek\">ἐπληθύνθην</span>; perfeito, terceira pessoa do singular <span class=\"greek\">πεπλήθυνται</span>, particípio <span class=\"greek\">πεπληθυμμένος</span> LXX (Aeschyl.+; LXX; pseudoepígrafos; Jos., C. Ap. 2, 139 e outros; Ath. 6, 4).</p><p class=\"entry-text\">① Fazer tornar-se maior em número; transitivo.</p><p class=\"entry-text\">ⓐ Aumentar, multiplicar, na voz ativa (En 16:3; TestJos 11:7; JosAs 21 p. 71, 21 Bat.), em nossa literatura sempre tendo Deus por agente: <span class=\"greek\">τι</span>, alguma coisa; <span class=\"greek\">τὸν</span> <span class=\"greek\">σπόρον</span> <span class=\"greek\">ὑμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:10</a>; <span class=\"greek\">ἔθνη</span>, 1 Cl 59:3. Da promessa divina a Abraão: <span class=\"greek\">πληθύνων</span> <span class=\"greek\">πληθυνῶ</span> <span class=\"greek\">σε</span>, «certamente te multiplicarei», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:14</a> (Gen 22:17). <span class=\"greek\">κύριος</span> <span class=\"greek\">ἐπλήθυνεν</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κόποις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">αὐτῶν</span>, «o Senhor lhes concedeu abundância no trabalho de suas mãos», Hs 9, 24, 3. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">κτίσας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πληθύνας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αὐξήσας</span>, v 1, 1, 6.</p><p class=\"entry-text\">ⓑ Ser multiplicado, crescer, aumentar, na voz passiva (En 5:5, 9), em número: <span class=\"greek\">ἐπληθύνετο</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀριθμὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μαθητῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:7</a>. <span class=\"greek\">ηὔξησεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπληθύνθη</span>, 7:17 (cf. Ex 1:7).—9:31; D 16:3. <span class=\"greek\">αὐξάνεσθε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πληθύνεσθε</span> (Gen 1:28; cf. SibOr 1, 57; Herm. Wr. 3, 3 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐξάνεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐξήσει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πληθύνεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πλήθει</span>), 1 Cl 33:6; B 6:12; cf. v. 18.—Do crescimento da pregação cristã, expresso pelo número de convertidos: <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ηὔξανεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπληθύνετο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:24</a>. Da propagação da impiedade: <span class=\"greek\">τὸ</span> <span class=\"greek\">πληθυνθῆναι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀνομίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:12</a>. Como fórmula de votos piedosos (cf. Da 4:1 Theod., 37c LXX; 6:26 Theod.): <span class=\"greek\">χάρις</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰρήνη</span> <span class=\"greek\">πληθυνθείη</span>, «que a graça e a paz vos sejam concedidas em medida cada vez maior», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:2</a>. Cf. Jd 2; 1 Cl inscrição; Pol inscrição; MPol inscrição. Cf. também Dg 11:5.</p><p class=\"entry-text\">② Aumentar muito em número, crescer, aumentar, intransitivo (Herodian 3, 8, 8; TestIss 1:11; AscIs 2:5; Jos., Bell. 5, 338; Ex 1:20; Sir 16:2; 23:3; 1 Macc 1:9; cf. Anz 296s.; Thackeray 282): <span class=\"greek\">πληθυνόντων</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μαθητῶν</span>, «quando os discípulos estavam aumentando [em número]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:1</a>; 19:20 D.—DELG s.v. <span class=\"greek\">πίμπλημι</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλήκτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλήκτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πλήσσω</span>; Aristot., Eth. Eud. 2, 3; Plut., Dio 971 [30, 4], Marcell. 298 [1, 2]; Diog. L. 6, 38; Ps 34:15 Sym.), pessoa belicosa, valentão, numa lista de qualidades relativas a um supervisor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:7</a>.—DELG s.v. <span class=\"greek\">πλήσσω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλημμέλεια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλημμέλεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πλημμελέω</span> «errar»; Democr. 46; Pla. e outros; LXX). O sentido primário, «nota falsa» em música, conduz à extensão figurada: algo contrário a um padrão geralmente reconhecido, frequentemente de infração cultual ou legal; falta, erro, pecado, transgressão (Aristot. 1251a, 31 <span class=\"greek\">ἀσέβεια</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">πλ</span>.; Jos., C. Ap. 2, 250; restituído em POxy 850 [AcJ], 30). <span class=\"greek\">θυσίαι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πλημμελείας</span>, «sacrifícios pelo pecado e pela transgressão [culpa]» (LXX, especialmente Lev 7:37), 1 Cl 41:2. Plural (Plut., Mor. 168d <span class=\"greek\">ἁμαρτίαι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πλημμέλειαι</span>; Philo, Mos. 2, 230; Jos., Bell. 5, 392), 60:1 (com <span class=\"greek\">ἀνομίαι</span>, <span class=\"greek\">ἀδικίαι</span>, <span class=\"greek\">παραπτώματα</span>).—Dodd 76.—DELG s.v. <span class=\"greek\">πλημμελής</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλήμμυρα, ης</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλήμμυρα</span>, <span class=\"greek\">ης</span> (sobre a formação, ver Schwyzer I 475, 3 e L-S-J-M s.v. <span class=\"greek\">πλημυρίς</span> «elevação do mar, inundação»; sobre a forma do genitivo [-<span class=\"greek\">α</span> no texto recebido, Sod., Vog., Bov.], ver B-D-F §43, 1; Mlt-H. 118; sobre a grafia, Mlt-H. 101; 274; ver também PKatz, TLZ 83, ’58, 315), <span class=\"greek\">ἡ</span> (Dionys. Hal. 1, 71; Crinagoras nº 33, 1; Plut., Rom. 19 [3, 6], Caes. 726 [38, 4], Mor. 897bc; Arrian, Ind. 21, 3; 6; POxy 1409, 17; Job 40:23 <span class=\"greek\">ἐὰν</span> <span class=\"greek\">γένηται</span> <span class=\"greek\">πλήμμυρα</span>; Philo, Op. M. 58, Leg. All. 1, 34, Abr. 92, Mos. 1, 202; 2, 195), transbordamento de uma massa de água, cheia, inundação: <span class=\"greek\">πλημμύρης</span> <span class=\"greek\">γενομένης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a>.—Sobre a grafia com um único <span class=\"greek\">μ</span> (leitura variante), própria de período mais antigo da língua, ver Mlt-H. p. 101; 274s.; JWackernagel, Kl. Schr. ’53, 1164, 1.—DELG s.v. <span class=\"greek\">πλημυρίς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλήν</h1><div class=\"entry-meta\"><span>partícula; advérbio; preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλήν</span></p><p class=\"entry-text\">① Advérbio usado como conjunção (trágicos e posteriores), no começo de frase ou oração; marcador daquilo que se acrescenta para consideração em contraste.</p><p class=\"entry-text\">ⓐ Adversativo: mas; <span class=\"greek\">μὲν</span> … <span class=\"greek\">πλήν</span>, «de fato … mas» (ver B-D-F §447, 6; Rob. 1187), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:22</a>.</p><p class=\"entry-text\">ⓑ Apenas, não obstante, porém (<span class=\"greek\">πλήν</span>, mais que <span class=\"greek\">ἀλλά</span>, é a palavra genuinamente coloquial para essa ideia [Schmid I 133]), assim em Mt e Lk, mas não em Ac (B-D-F §449, 1.—Ver L-S-J-M s.v. B III 2): <span class=\"greek\">πλὴν</span> <span class=\"greek\">λέγω</span> <span class=\"greek\">ὑμῖν</span>, «não obstante, eu vos digo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:22</a>, 24 (<span class=\"greek\">ἀμὴν</span> <span class=\"greek\">λέγω</span> <span class=\"greek\">ὑμῖν</span> no trecho correspondente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:15</a>); 26:64 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:12</a> <span class=\"greek\">λέγω</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὑμῖν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:13</a> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">λέγω</span> <span class=\"greek\">ὑμῖν</span>; cf. ApcMos 39 <span class=\"greek\">πλὴν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">λέγω</span> <span class=\"greek\">σοι</span>). <span class=\"greek\">πλὴν</span> <span class=\"greek\">οὐαί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:1</a> (<span class=\"greek\">οὐαὶ</span> <span class=\"greek\">δὲ</span>, leitura variante). <span class=\"greek\">πλὴν</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">θέλω</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ὡς</span> <span class=\"greek\">σύ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:39</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:42</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:36</a> <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">τί</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">θέλω</span>).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:24</a>, 35; 10:11, 14, 20; 11:41; 13:33; 18:8; 19:27; 22:21.—Também em retrospectiva de uma negação (TestZeb 1:5; JosAs 23:15; ApcMos 19; Just., D. 44, 2; 88, 7; 93, 1): <span class=\"greek\">μὴ</span> <span class=\"greek\">κλαίετε</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐμέ</span>, <span class=\"greek\">πλὴν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἑαυτὰς</span> <span class=\"greek\">κλαίετε</span>, «não choreis por mim, mas [antes] por vós mesmas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:28</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">ζητεῖτε</span> … <span class=\"greek\">πλὴν</span> <span class=\"greek\">ζητεῖτε</span>, 12:(29–)31.</p><p class=\"entry-text\">ⓒ Somente, em todo caso, por outro lado, mas, interrompendo uma discussão e ressaltando o essencial (JosAs 14:9; Mel., P. 95, 729; UPZ 110, 207 [164 a.C.]; Sb 6994, 28; B-D-F §449, 2; Rob. 1187; ver L-S-J-M s.v. B III 2): assim em Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:16</a>; 4:14. Talvez 1:18 <span class=\"greek\">τί</span> <span class=\"greek\">γάρ</span>; <span class=\"greek\">πλὴν</span> <span class=\"greek\">ὅτι</span> …, «que importa, pois? Em todo caso …» (mas o texto é incerto; ver também d); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:25</a>.</p><p class=\"entry-text\">ⓓ <span class=\"greek\">πλὴν</span> <span class=\"greek\">ὅτι</span>, «exceto que» (Aristoph., Pla., Hdt. e outros; Hero Alex. I p. 188, 1; Dionys. Hal., Comp. Verb. 14, fim; Plut., Cato Maj. 350 [23, 6]; Just., A I, 21, 4; D. 71, 3; Schwyzer II 543), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:23</a>. Talvez também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:18</a> (ver c acima), <span class=\"greek\">τί</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">πλὴν</span> <span class=\"greek\">ὅτι</span> …; «qual será, então, o resultado, exceto que …?».</p><p class=\"entry-text\">ⓔ Interrompendo e passando a novo assunto: somente, mas (exemplos em L-S-J-M, <span class=\"greek\">πλήν</span> B III 2.—Polyb. 2, 17, 1; Plut., Pericl. 170 [34, 1]; Tat. 36, 1 começam novas seções com <span class=\"greek\">πλήν</span>): <span class=\"greek\">πλὴν</span> <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">χεὶρ</span> <span class=\"greek\">κτλ</span>., «mas eis que a mão [de meu delator] está comigo à mesa» (a narrativa passa da instituição da Eucaristia à predição do papel de Judas como delator), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:21</a>.</p><p class=\"entry-text\">② Usado como preposição com genitivo, marcando exceção: exceto, em referência a pessoa ou coisa (desde Od. 8, 207; inscrições, papiros, LXX [Johannessohn, Präp. 342–44; Schwyzer II 542]; TestSol 13:12 C; TestAbr A 8 p. 85, 22 [Stone p. 18]; TestIss 7:2; JosAs 2:16; 5:10; ApcSed; Ar. 15, 3; Just., A I, 53, 6 e outros; B-D-F §216, 2; Rob. 646 [cf. o uso de <span class=\"greek\">παρὰ</span> com acusativo nesse sentido, Plut., Cat. Min. 768 (20), Ant. 918 (5); ver L-S-J-M <span class=\"greek\">παρὰ</span> C III 5b]), sobretudo após enunciados negativos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:32</a> (<span class=\"greek\">οὐκ</span> <span class=\"greek\">ἄλλος</span> <span class=\"greek\">πλήν</span>, como Jos., Ant. 1, 182); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:10</a> leitura variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:28</a>; 27:22. Após enunciado afirmativo (Thu. 4, 54, 2; X., An. 2, 4, 27; Appian, Liby. 14 §59; Jos., Ant. 12, 422 <span class=\"greek\">ἔφυγον</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">πλὴν</span> <span class=\"greek\">ὀκτακοσίων</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:1</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλήρης, ες</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλήρης</span>, <span class=\"greek\">ες</span> (Aeschyl., Hdt.+).</p><p class=\"entry-text\">① Relativo a conter em si tudo quanto pode comportar: cheio, pleno.</p><p class=\"entry-text\">ⓐ De coisas.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com <span class=\"greek\">τινός</span>, «cheio de algo» (Diod S 2, 4, 2 <span class=\"greek\">λίμνη</span> <span class=\"greek\">πλήρης</span> <span class=\"greek\">ἰχθύων</span>; Appian, Hann. 15 §66; PSI 422, 14 [séc. III a.C.] <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">ῥηγμῶν</span> [fissuras] <span class=\"greek\">πλ</span>. <span class=\"greek\">ἐστίν</span>; Num 7:26; Dt 6:11; Diog. L. 6, 37 <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">αὐτοῦ</span> [= <span class=\"greek\">θεοῦ</span>] <span class=\"greek\">πλήρη</span>): cestos <span class=\"greek\">κλασμάτων</span> <span class=\"greek\">πλ</span>., «cheios de pedaços», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:19</a>; cf. 6:43 leitura variante. Uma vinha <span class=\"greek\">βοτανῶν</span> <span class=\"greek\">πλ</span>., «cheia de ervas daninhas», Hs 5, 2, 3. De um monte: <span class=\"greek\">ἀκανθῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τριβόλων</span> <span class=\"greek\">πλ</span>., 9, 1, 5; <span class=\"greek\">πηγῶν</span> <span class=\"greek\">πλ</span>., v. 8. Árvores <span class=\"greek\">καρπῶν</span> <span class=\"greek\">πλ</span>., 9, 28, 1. <span class=\"greek\">πλήρης</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κτίσις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δόξης</span> <span class=\"greek\">αὐτοῦ</span>, 1 Cl 34:6 (Is 6:3). <span class=\"greek\">εἰς</span> <span class=\"greek\">συναγωγὴν</span> <span class=\"greek\">πλήρη</span> <span class=\"greek\">ἀνδρῶν</span> <span class=\"greek\">δικαίων</span>, Hm 11:14.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Em emprego absoluto: <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">σπυρίδες</span> <span class=\"greek\">πλήρεις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:37</a>; cf. 14:20 (GrBar 15:2 <span class=\"greek\">τἀ</span> <span class=\"greek\">κανίσκια</span> <span class=\"greek\">πλήρη</span>). De vasos: Hm 12, 5, 3ab.—<span class=\"greek\">ἐκ</span> <span class=\"greek\">πλήρους</span> (SIG 1104, 21 <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πλήρους</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δίκαια</span>; PTebt 106, 20 [séc. II a.C.]; 281, 22; BGU 584, 6 e frequentemente em papiros = «na quantia integral»; segundo CTurner, JTS 21, 1920, 198, nota 1, trata-se de latinismo para «in pleno»): integralmente, em toda a plenitude, <span class=\"greek\">τι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πλ</span>., Hv 2, 2, 6.</p><p class=\"entry-text\">ⓑ De pessoas, com genitivo: <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">πλήρης</span> <span class=\"greek\">λέπρας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:12</a> (= inteiramente coberto por ela, como 4 Km 7:15; Is 1:15). Predominantemente «cheio» de poder, dom, sentimento, qualidade característica etc. (Eur., El. 384; Pla., Plt. 310d; Jos., Vi. 192 <span class=\"greek\">πλ</span>. <span class=\"greek\">συνέσεως</span>; Just., D. 93, 2.—Procop. Soph., Ep. 68 <span class=\"greek\">πλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>): <span class=\"greek\">πλ</span>. <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.55\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:55</a>. <span class=\"greek\">πλ</span>. <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πίστεως</span>, 11:24; cf. 6:5. <span class=\"greek\">πλ</span>. <span class=\"greek\">πνεύματος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σοφίας</span>, v. 3. <span class=\"greek\">πλ</span>. <span class=\"greek\">χάριτος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀληθείας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:14</a> (ver fim deste artigo). <span class=\"greek\">πλ</span>. <span class=\"greek\">χάριτος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δυνάμεως</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:8</a>. <span class=\"greek\">πλ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, MPol 7:3. <span class=\"greek\">πλ</span>. <span class=\"greek\">ἔργων</span> <span class=\"greek\">ἀγαθῶν</span>, «rico em boas obras», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:36</a>. <span class=\"greek\">πάσης</span> <span class=\"greek\">κακίας</span> <span class=\"greek\">πλ</span>., 1 Cl 45:7 (Maximus Tyr. 34, 3a <span class=\"greek\">πλ</span>. <span class=\"greek\">κακῶν</span>; igualmente Appian, Bell. Civ. 3, 19 §69, que chama os assassinos de César <span class=\"greek\">φόνου</span> <span class=\"greek\">πλήρεις</span>). <span class=\"greek\">πλ</span>. <span class=\"greek\">παντὸς</span> <span class=\"greek\">δόλου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:10</a> (<span class=\"greek\">πλήρης</span> <span class=\"greek\">δόλου</span>, Sir 1:30; 19:26; Jer 5:27). <span class=\"greek\">γενόμενοι</span> <span class=\"greek\">πλήρεις</span> <span class=\"greek\">θυμοῦ</span>, 19:28 (cf. Petosiris, Fgm. 21, linha 29 <span class=\"greek\">πλῆρες</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">γενήσεται</span>). <span class=\"greek\">πλ</span>. <span class=\"greek\">ἁμαρτιῶν</span> (cf. Is 1:4), Hs 9, 23, 4. <span class=\"greek\">πλ</span>. <span class=\"greek\">πάσης</span> <span class=\"greek\">ἁπλότητος</span>, Hv 1, 2, 4.—De um coração (cf. 2 Ch 15:17; 1 Esdr 1:21): <span class=\"greek\">πλ</span>. <span class=\"greek\">εἰδωλολατρίας</span>, B 16:7.—Saciado, saturado de: <span class=\"greek\">πλ</span>. <span class=\"greek\">εἰμὶ</span> <span class=\"greek\">ὁλοκαυτωμάτων</span>, «estou farto de holocaustos», B 2:5 (Is 1:11).</p><p class=\"entry-text\">② Relativo a estar completo e nada lhe faltar: completo, pleno, integral (Hdt. e outros; LXX; AssMos Fgm. e, Denis p. 65): <span class=\"greek\">μισθὸς</span> <span class=\"greek\">πλ</span>., «recompensa integral» (X., An. 7, 5, 5; Ruth 2:12; <span class=\"greek\">πλ</span>. é termo favorito dos papiros para soma completa), 2J 8. <span class=\"greek\">πλ</span>. <span class=\"greek\">σῖτος</span>, «cereal plenamente maduro» (cf. os <span class=\"greek\">στάχυες</span> «inteiramente desenvolvidos», Gen 41:7, 22, 24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:28</a> leitura variante (outros manuscritos <span class=\"greek\">πλήρης</span> <span class=\"greek\">σῖτον</span>, <span class=\"greek\">πλήρη</span> <span class=\"greek\">ς</span>.). <span class=\"greek\">νηστεία</span> <span class=\"greek\">πλ</span>., «jejum completo», Hs 5, 1, 3. <span class=\"greek\">πλ</span>. <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἔκχυσις</span>, «pleno derramamento do Espírito», 1 Cl 2:2.—De pessoas completas em determinado aspecto ou que possuem plenamente alguma coisa: <span class=\"greek\">πλ</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>; <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτοις</span> <span class=\"greek\">πλ</span>., 2 Cl 16:4. <span class=\"greek\">πλ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span>, Hm 5, 2, 1; 12, 5, 4.—Em algumas passagens mencionadas, <span class=\"greek\">πλήρης</span> é indeclinável, embora nunca sem leitura variante e quase só quando aparece com genitivo, correspondendo a expressões como «uma obra cheia de erros»: <span class=\"greek\">τὴν</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">αὐτοῦ</span> … <span class=\"greek\">πλήρης</span> (referindo-se a <span class=\"greek\">αὐτοῦ</span>) <span class=\"greek\">χάριτος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀληθείας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:14</a> (cf. CTurner, JTS 1, 1900, 120ss.; 561s.). <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">πλήρης</span> <span class=\"greek\">πίστεως</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:5</a> (leitura variante <span class=\"greek\">πλήρη</span>). Encontra-se como leitura variante itacística em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:3</a>, 5; 19:28; e sem genitivo em 2J 8, leitura variante (ver aparato de N.25). Exemplos desse emprego com genitivo ocorrem desde o séc. II a.C.; a partir do séc. I d.C. são frequentes no grego helenístico coloquial: PLeid C II, 14 (160 a.C.); tabuinha de madeira egípcia da época de Augusto, RevArch 29, 1875, 233s. = Sb 3553, 7; BGU 707, 15; POxy 237 IV, 14 (todos três do séc. II d.C.); Mitt-Wilck. I/2, 499, 9 (sécs. II/III d.C.); En 21:7. Ver os exemplos em Crönert 179, 4, e também Mayser 63s. (com bibliografia); 297; Dssm., LO 99s. [LAE 125ss.]; Thackeray 176s.; Reinhold 53; Borger, GGA 139 (bibliografia); B-D-F §137, 1; Mlt. 50; Rob. 275s.—B. 931. Frisk. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πληροφορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πληροφορέω</span> (*<span class=\"greek\">πληροφόρος</span> [<span class=\"greek\">πλήρης</span>, <span class=\"greek\">φέρω</span> por intermédio de <span class=\"greek\">φορέω</span>]); primeiro aoristo imperativo <span class=\"greek\">πληροφόρησον</span>, infinitivo <span class=\"greek\">πληροφορῆσαι</span>. Passivo: primeiro aoristo infinitivo <span class=\"greek\">πληροφορηθῆναι</span>, particípio <span class=\"greek\">πληροφορηθείς</span>; perfeito <span class=\"greek\">πεπληροφόρημαι</span>, particípio <span class=\"greek\">πεπληροφορημένος</span> (Ctesias: 688 Fgm. 14 [42] Jac. p. 467, 9s. [= Fgm. 29, 39 Müller]; outras ocorrências desde LXX Eccl 8:11; TestAbr A 1 p. 78, 7s. [Stone p. 4], B 7 p. 112, 5 leitura variante [Stone p. 72; NTS 1, ’54/55, 223]; TestGad 2:4; BGU 665 II, 2 [séc. I d.C.]; APF 5, 1913, 383 nº 69b, 5 [sécs. I/II d.C.]; BGU 747 I, 22 [139 d.C.]; PAmh 66 II, 42; POxy 509, 10 [ambos do séc. II d.C.]; Vett. Val. 43, 18; 226, 20.—Dssm., LO 67s. [LAE 82s.]).</p><p class=\"entry-text\">① Encher (completamente), cumprir plenamente; sinônimo de <span class=\"greek\">πληρόω</span>, que ocasionalmente ocorre como leitura variante. Em nossa literatura, apenas figuradamente.</p><p class=\"entry-text\">ⓐ Tendo coisa por objeto: <span class=\"greek\">τι</span>, alguma coisa; acrescentar a algo aquilo que lhe falta, algo como completar, complementar, auxiliar: <span class=\"greek\">τὸν</span> <span class=\"greek\">πλοῦτον</span>, Hs 2:8a; <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχάς</span>, 8b.—<span class=\"greek\">τὴν</span> <span class=\"greek\">διακονίαν</span> <span class=\"greek\">σου</span> <span class=\"greek\">πληροφόρησον</span>, «cumpre plenamente o teu ministério», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:5</a>. Também na passiva: <span class=\"greek\">ἵνα</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κήρυγμα</span> <span class=\"greek\">πληροφορηθῇ</span>, v. 17.—De um pedido atendido: Hm 9:2 (nos papiros, a palavra é usada principalmente no sentido de «satisfazer completamente uma exigência»).—Realizar: <span class=\"greek\">τὰ</span> <span class=\"greek\">πεπληροφορημένα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">πράγματα</span>, «as coisas que se realizaram entre nós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:1</a> (ver M-JLagrange, Le sens de Luc 1:1 d’après les papyrus: Bull. d’ancienne Litt. et d’Arch. chrét. 2, 1912, 96–100; OPiper, Union Sem. Rev. 57, ’45, 15–25: Lk [e Ac] como «cumprimento» do AT.—Ver também a bibliografia indicada em <span class=\"greek\">παρακολουθέω</span>, fim). Alguns (p. ex., KRengstorf, Das NT Deutsch ’37, ad loc.) traduziriam aqui «sobre as quais há plena convicção entre nós», situando a passiva sob 2. Entretanto, considerando a ênfase temática de Lk na <span class=\"greek\">βουλή</span> de Deus (ver 2b), parece mais provável a ideia de realização de coisas planejadas (ver Lagrange).</p><p class=\"entry-text\">ⓑ De pessoas: <span class=\"greek\">πεπληροφορημένος</span> <span class=\"greek\">τινός</span>, «cheio de algo»: <span class=\"greek\">ἀγάπης</span>, «de amor», 1 Cl 54:1 (com <span class=\"greek\">εὔσπλαγχνος</span>). Talvez também com <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (<span class=\"greek\">πληρόω</span> 1b): <span class=\"greek\">πεπληροφορημένοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">θελήματι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «plenos de tudo aquilo que está [de acordo com] a vontade de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:12</a> (ver também 2 abaixo).</p><p class=\"entry-text\">② Convencer plenamente (Ctesias: 688 Fgm. 14, 42 Jac. p. 467, 9s.; AcPh 9 [Aa II, 2 p. 5, 20]; Ps.-Clem., Hom. 1, 20 e outros); na passiva: estar plenamente convencido, seguro, certo (cf. TestGad 2:4 <span class=\"greek\">ἐπληροφορήθημεν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀναιρέσεως</span> <span class=\"greek\">αὐτοῦ</span> = «estávamos inteiramente tomados da intenção de matá-lo».—Hegesippus em Eus., HE 2, 23, 14; Martyr. Pionii 4, 17 em HMusurillo, The Acts of the Christian Martyrs ’72); seguido de <span class=\"greek\">ὅτι</span>: estar plenamente convencido de que (Ps.-Clem., Hom. p. 9, 22 Lag.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:21</a>; IMg 8:2. Ter fé perfeita (isto é, não limitada por qualquer dúvida): <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>, «no Senhor», ISm 1:1. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «em algo», IMg 11; IPhld inscrição.—Em emprego absoluto (se <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">κτλ</span>. [ver 1b acima] se liga a <span class=\"greek\">σταθῆτε</span>): estar inteiramente seguro: <span class=\"greek\">τέλειοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πεπληροφορημένοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:12</a> (mas, nesse caso, também pode significar «completos, consumados»). <span class=\"greek\">πληροφορηθέντες</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀναστάσεως</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, «plenamente assegurados pela ressurreição do Senhor», 1 Cl 42:3. <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἰδίῳ</span> <span class=\"greek\">νοὶ̈</span> <span class=\"greek\">πληροφορείσθω</span>, «cada qual esteja plenamente convencido em seu próprio entendimento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:5</a> (JBeckler, Biblica 65, ’84, 364).—Ltzm., Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:21</a>; Dssm., LO4 67s. [LAE 86s.].—DELG s.v. <span class=\"greek\">πίμπλημι</span>. M-M. EDNT. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πληροφορία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πληροφορία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πληροφορέω</span>), estado de certeza completa, plena convicção, certeza (PGiss 87, 25 [séc. II d.C.]; Rhet. Gr. VII 108, 3; Hesychius = <span class=\"greek\">βεβαιότης</span>; cf. <span class=\"greek\">πληροφορέω</span> 2); esse significado provavelmente ocorre nas passagens de nossa literatura. <span class=\"greek\">πλοῦτος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πληροφορίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">συνέσεως</span>, «riqueza de plena convicção, tal como a compreensão a proporciona», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:2</a>. <span class=\"greek\">ἐν</span> … <span class=\"greek\">πλ</span>. <span class=\"greek\">πολλῇ</span>, «com plena convicção», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:5</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλπίδος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:11</a>. <span class=\"greek\">πλ</span>. <span class=\"greek\">πίστεως</span>, 10:22. <span class=\"greek\">πλ</span>. <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span>, «a certeza que o Espírito Santo concede», 1 Cl 42:3; mas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:11</a>; 10:22; 1 Cl 42:3 o sentido de «plenitude» também merece atenção. Igualmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:29</a>, leitura variante.—DELG s.v. <span class=\"greek\">πίμπλημι</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πληρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πληρόω</span> imperfeito, terceira pessoa do singular <span class=\"greek\">ἐπλήρου</span>; futuro <span class=\"greek\">πληρώσω</span>; primeiro aoristo <span class=\"greek\">ἐπλήρωσα</span>; perfeito <span class=\"greek\">πεπλήρωκα</span>; mais-que-perfeito, terceira pessoa do singular <span class=\"greek\">πεπληρώκει</span> (sobre a omissão do aumento, B-D-F §66, 1; Mlt-H. 190). Passivo: imperfeito <span class=\"greek\">ἐπληρούμην</span>; primeiro futuro <span class=\"greek\">πληρωθήσομαι</span>; primeiro aoristo <span class=\"greek\">ἐπληρώθην</span>; perfeito <span class=\"greek\">πεπλήρωμαι</span>; mais-que-perfeito, terceira pessoa do singular <span class=\"greek\">πεπλήρωτο</span> (ver B-D-F §66, 1; Mlt-H. 190) (Aeschyl., Hdt.+).</p><p class=\"entry-text\">① Tornar cheio, encher (completamente).</p><p class=\"entry-text\">ⓐ De coisas: <span class=\"greek\">τι</span>, algo; <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> (Orig., C. Cels. 3, 8, 29), B 6:12 (Gen 1:28; cf. Ocellus [séc. II a.C.], cap. 46 Harder [1926], <span class=\"greek\">τὸν</span> <span class=\"greek\">πλείονα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">πληροῦσθαι</span>, «ser preenchida a maior parte da terra» por seus descendentes). Passiva, acerca de uma rede: <span class=\"greek\">ἐπληρώθη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:48</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">φάραγξ</span> <span class=\"greek\">πληρωθήσεται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:5</a> (Is 40:4). <span class=\"greek\">ὀθόνη</span> <span class=\"greek\">πλοίου</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">πληρουμένη</span>, «vela de navio enfunada pelo vento», MPol 15:2.—<span class=\"greek\">τόπον</span> <span class=\"greek\">πληρῶσαι</span>, «ocupar um espaço», Hs 9, 7, 5. <span class=\"greek\">ἐπλήρωσεν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">τύπους</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λίθων</span>, «preencheu os lugares marcados pelas pedras [que haviam sido retiradas]», 9, 10, 2.—Também de sons e odores (bem como da luz: escólio a Pla. 914b): <span class=\"greek\">ἦχος</span> <span class=\"greek\">ἐπλήρωσεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span>, «um som encheu a casa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:2</a> (Diod S 11, 24, 4 <span class=\"greek\">αἱ</span> <span class=\"greek\">οἰκίαι</span> <span class=\"greek\">πένθους</span> <span class=\"greek\">ἐπληροῦντο</span> = «as casas enchiam-se de clamores de luto»). <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">ἐπληρώθη</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀσμῆς</span>, «a casa se encheu da fragrância», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:3</a> (cf. Diod S 4, 64, 1 <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">πληρώσειν</span> <span class=\"greek\">ἀτυχημάτων</span>; Ael. Aristid. 36, 84 K. = 48 p. 471 D.: <span class=\"greek\">ὅταν</span> <span class=\"greek\">οἴκημα</span> <span class=\"greek\">πληρωθῇ</span>; TestAbr A 4 p. 80, 23s. [Stone p. 8] <span class=\"greek\">πλήρωσον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">ἡμῶν</span> [com plantas aromáticas]).—Também, de outras maneiras, do preenchimento de objetos impessoais por coisas ou qualidades reais, mas intangíveis: <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">αὐτοῦ</span> (isto é, do mártir Policarpo) <span class=\"greek\">χάριτος</span> <span class=\"greek\">ἐπληροῦτο</span>, MPol 12:1 (<span class=\"greek\">χάρις</span> 1 e 4). <span class=\"greek\">πεπληρώκατε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἰερουσαλὴμ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διδαχῆς</span> <span class=\"greek\">ὑμῶν</span>, «enchestes Jerusalém com vosso ensinamento», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:28</a>. <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">πληρώσατε</span> (imperativo aoristo como exigência retórica; leituras variantes <span class=\"greek\">πληρώσετε</span>, <span class=\"greek\">ἐπληρώσατε</span>) <span class=\"greek\">τὸ</span> <span class=\"greek\">μέτρον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πατέρων</span> <span class=\"greek\">ὑμῶν</span>, «completai a medida de vossos pais», da medida de pecados (cf. Da 8:23), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:32</a>; cf. <span class=\"greek\">ἐπεὶ</span> <span class=\"greek\">πεπλήρωτο</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμετέρα</span> <span class=\"greek\">ἀδικία</span>, Dg 9:2. <span class=\"greek\">θεὸς</span> <span class=\"greek\">πληρώσει</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">χρείαν</span> <span class=\"greek\">ὑμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:19</a> (cf. Thu. 1, 70, 7). <span class=\"greek\">πλ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> <span class=\"greek\">τινός</span>, «encher o coração de alguém», isto é, apoderar-se dele completamente (cf. Eccl 9:3): <span class=\"greek\">ἡ</span> <span class=\"greek\">λύπη</span> <span class=\"greek\">πεπλήρωκεν</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">καρδίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:6</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τί</span> <span class=\"greek\">ἐπλήρωσεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σατανᾶς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">καρδίαν</span> <span class=\"greek\">σοὺ</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:3</a> (Ad’Alès, RSR 24, ’34, 199s.; 474s. prefere a leitura variante <span class=\"greek\">ἐπήρωσεν</span>; contra ele, LSt.-Paul Girard, Mém. de l’inst. franc. du Caire 67, ’37, 309–12). <span class=\"greek\">ὁ</span> <span class=\"greek\">ψευδοπροφήτης</span> <span class=\"greek\">πληροῖ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχάς</span>, Hm 11:2 (<span class=\"greek\">θείου</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">πληρώσαντος</span> … <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχάς</span>, Orig., C. Cels. 3, 81, 20).—De Cristo, que atravessou todas as esferas cósmicas: <span class=\"greek\">ἵνα</span> <span class=\"greek\">πληρώσῃ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:10</a> (cf. Jer 23:24; Philo, Leg. All. 3, 4 <span class=\"greek\">πάντα</span> <span class=\"greek\">πεπλήρωκεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, Vita Mos. 2, 238, Conf. Lingu. 136; Ath. 8, 3 <span class=\"greek\">πάντα</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦτου</span> <span class=\"greek\">πεπλήρωται</span>). Médio no sentido ativo (B-D-F §316, 1; Rob. 805s.; cf. X., Hell. 6, 2, 14; 35 e outros; Plut., Alc. 211 [35, 6]): <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">πληρουμένου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:23</a> (<span class=\"greek\">πλήρωμα</span> 2).</p><p class=\"entry-text\">ⓑ De pessoas: encher de poderes, qualidades etc.; <span class=\"greek\">τινά</span>, alguém: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προφητικοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">πληροῖ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνθρωπον</span>, Hm 11:9a. <span class=\"greek\">τινά</span> <span class=\"greek\">τινος</span>, «encher alguém de algo» (OdeSol 11:2; B-D-F §172; Rob. 510): <span class=\"greek\">πληρώσεις</span> <span class=\"greek\">με</span> <span class=\"greek\">εὐφροσύνης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:28</a> (Ps 15:11). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:13</a> (cf. POxy 3313, 3 <span class=\"greek\">χαρ</span>[<span class=\"greek\">ᾶ</span> <span class=\"greek\">ἡμ</span>]<span class=\"greek\">ᾶ</span> <span class=\"greek\">ἐπλήρωσα</span>). <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span>, «encher alguém de algo» (B-D-F §195, 2): <span class=\"greek\">ὁ</span> <span class=\"greek\">διάβολος</span> <span class=\"greek\">πληροῖ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πνεύματι</span>, Hm 11:3.—Principalmente na passiva: presente, imperfeito, futuro e aoristo, «ficar cheio» (escólio a Pla. 856e, acerca de <span class=\"greek\">μάντις</span>: <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πληροῦσθαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>); no perfeito, «ter sido enchido, estar cheio»: com genitivo de coisa (Diod S 20, 21, 3 <span class=\"greek\">τῶν</span> <span class=\"greek\">βασιλείων</span> <span class=\"greek\">πεπληρωμένων</span> <span class=\"greek\">φόνων</span> = «estando o palácio cheio de atos homicidas»; Diog. L. 5, 42 <span class=\"greek\">τὸ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἀρετῆς</span> <span class=\"greek\">πεπληρῶσθαι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:40</a> leitura variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.52\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:52</a> (Jos., Ant. 15, 421 <span class=\"greek\">ἐπληρώθη</span> <span class=\"greek\">χαρᾶς</span>; cf. Just., A I, 49, 5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:4</a>; Dg 10:3; IRo inscrição; Ox 840, 40s.—Com dativo de coisa (Aeschyl., Sept. 464 e outros; Parthenius 10, 4 <span class=\"greek\">ἄχει</span> <span class=\"greek\">ἐπληρώθη</span>; 2 Macc 7:21; 3 Macc 4:16; 5:30; Just., D. 7, 1 <span class=\"greek\">πνεύματι</span>; cf. BGU 1108, 12 [séc. I a.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:4</a>; Hm 5, 2, 7; 11:9b leitura variante (em lugar de <span class=\"greek\">πλησθεί</span>).—Com acusativo de coisa (os papiros empregam ativo e passivo com acusativo no sentido de «liquidar integralmente mediante o pagamento ou entrega de algo»: PLond II, 243, 11 p. 300 [346 d.C.]; 251, 30; POxy 1133, 8; 1134, 6; PFlor 27, 3 e outros; B-D-F §159, 1; Rob. 510): <span class=\"greek\">πεπληρωμένοι</span> <span class=\"greek\">καρπὸν</span> <span class=\"greek\">δικαιοσύνης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:11</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:9</a>.—Com <span class=\"greek\">ἐν</span> e dativo de coisa: <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span>, «com o Espírito», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:18</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">καί</span> <span class=\"greek\">ἀγάπῃ</span>, ISm inscrição. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:12</a> leitura variante, caso <span class=\"greek\">ἐν</span> <span class=\"greek\">κτλ</span>. se ligue a <span class=\"greek\">πεπληρωμένοι</span> (ver <span class=\"greek\">πληροφορέω</span> 1b); também merece atenção o sentido 3. <span class=\"greek\">ἐστὲ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">πεπληρωμένοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:10</a>, provavelmente é diferente: não significa «com ele», mas «nele» ou «por meio dele».—Em emprego absoluto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:19</a> (<span class=\"greek\">εἰς</span> indica o alvo; ver <span class=\"greek\">πλήρωμα</span> 3b). <span class=\"greek\">πεπλήρωμαι</span>, «estou bem suprido», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:18</a> (cf. Diod S 14, 62, 5 <span class=\"greek\">πληροῦν</span> <span class=\"greek\">τινα</span> = «suprir plenamente alguém»).</p><p class=\"entry-text\">② Completar um período de tempo, preencher, completar (Pla., Leg. 9, 866a, Tim. 39d; Plut., Lucull. 516 [35, 8]; POxy 275, 24 [66 d.C.] <span class=\"greek\">μέχρι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χρόνον</span> <span class=\"greek\">πληρωθῆναι</span>; 491, 6; PTebt 374, 10; BGU 1047 III, 12 e outros papiros; Gen 25:24; 29:21; Lev 8:33; 12:4; 25:30; Num 6:5; Tob 10:1; 1 Macc 3:49 e outros; TestAbr B; TestJob 28:1 <span class=\"greek\">ἐπλήρωσα</span> <span class=\"greek\">εἴκοσι</span> <span class=\"greek\">ἔτη</span>; ApcMos 13; Jos., Ant. 4, 78; 6, 49); em nossa literatura, apenas na passiva (Ps.-Callisth. 3, 17, 39; 41 <span class=\"greek\">πεπλήρωται</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἔτη</span>; Did., Gen. 195, 23): <span class=\"greek\">πεπλήρωται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">καιρός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:15</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:8</a>. <span class=\"greek\">χρόνος</span> em lugar de <span class=\"greek\">καιρός</span>: Hs 6, 5, 2; cf. <span class=\"greek\">πληρωθέντος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χρόνου</span> (no plural: Iren. 1, 17, 2 [Harv. I 168, 13]), «quando se esgotou o tempo», 1 Cl 25:2. <span class=\"greek\">πεπλήρωνται</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἡμέραι</span>, «os dias se esgotaram, chegaram ao fim», Hv 2, 2, 5. <span class=\"greek\">πληρωθέντων</span> … <span class=\"greek\">τῶν</span> <span class=\"greek\">ἡμερῶν</span>, GJs 5:2 (TestAbr B 1 p. 105, 4 [Stone p. 58]).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:23</a>. <span class=\"greek\">πεπλήρωται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὅρος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐτῶν</span>, final de Mk no manuscrito Freer, 6s. <span class=\"greek\">πληρωθέντων</span> <span class=\"greek\">ἐτῶν</span> <span class=\"greek\">τεσσερακοντα</span>, «decorridos quarenta anos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:30</a> (TestJud 9:2).—24:27; 1 Cl 25:5. <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐπληροῦτο</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τεσσερακονταετὴς</span> <span class=\"greek\">χρόνος</span>, «quando ele completava quarenta anos de idade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:23</a> (PFlor 382, 6; 11 <span class=\"greek\">ἑβδομήκοντα</span> <span class=\"greek\">ἔτη</span> <span class=\"greek\">ἐπλήρωσας</span>). <span class=\"greek\">ἐπληρώθησαν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μῆνες</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">εἶπεν</span> <span class=\"greek\">ἕξ</span>, «[Ana] completara o sexto mês, conforme [o anjo] dissera», GJs 5:2 (mas ver deStrycker, ad loc.).</p><p class=\"entry-text\">③ Levar à conclusão aquilo que já foi iniciado, completar, terminar (X., Hell. 4, 8, 16; Herodian 1, 5, 8; Olympiodorus, Vida de Platão p. 2 Westerm.: o hino iniciado; Himerius, Or. 6 [2], 14 <span class=\"greek\">πληρῶσαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπιθυμίαν</span> = «satisfazer plenamente o desejo», pois os persas queriam incorporar a seu vasto império uma pequena parte do Ocidente, isto é, a Grécia; ApcSed 13:1 <span class=\"greek\">τὴν</span> <span class=\"greek\">μετάνοιαν</span>): <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, «levar [a pregação do] evangelho à conclusão, proclamando-o nas regiões mais remotas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:19</a>; semelhantemente, <span class=\"greek\">πλ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">λόγον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:25</a>. <span class=\"greek\">πληρώσατέ</span> <span class=\"greek\">μου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χαράν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:2</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:11</a>.—Passiva: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:12</a> leitura variante (ver 1b acima). <span class=\"greek\">ὁ</span> <span class=\"greek\">πᾶς</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">πεπλήρωται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:14</a>: por causa do tempo passado, provavelmente se deve traduzir «toda a lei encontrou sua plena expressão numa só palavra» ou «está resumida sob um único enunciado» (ver <span class=\"greek\">λόγος</span> 2a; alguns classificariam a passagem em 4b). <span class=\"greek\">οὐχ</span> <span class=\"greek\">εὕρηκά</span> <span class=\"greek\">σου</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">πεπληρωμένα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:2</a>. O uso joanino fala da alegria que se torna completa (voz ativa em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:2</a>, ver acima): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:29</a>; 15:11; 16:24; 17:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:4</a>; 2J 12.</p><p class=\"entry-text\">④ Levar ao termo visado, cumprir uma profecia, obrigação, promessa, lei, pedido, propósito, desejo, esperança, dever, fado, destino etc. (Pla., Gorg. 63, 507e <span class=\"greek\">ἐπιθυμίας</span> [cf. TestJos 4:7 <span class=\"greek\">ἐπιθυμίαν</span>]; Herodian 2, 7, 6 <span class=\"greek\">ὑποσχέσεις</span>; Epict. 2, 9, 3; 8 <span class=\"greek\">ἐπαγγελίαν</span>; Plut., Cic. 869 [17, 5] <span class=\"greek\">τὸ</span> <span class=\"greek\">χρεών</span> [= destino]; Procop. Soph., Ep. 68 <span class=\"greek\">τ</span>. <span class=\"greek\">ἐλπίδας</span>; inscrição espartana em BSA 12, 1905/6, p. 452 [séc. I d.C.] <span class=\"greek\">τὰ</span> <span class=\"greek\">εἰθισμένα</span>; papiros, LXX; Philo, Praem. 83 <span class=\"greek\">τὰς</span> <span class=\"greek\">θείας</span> <span class=\"greek\">παραινέσεις</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κενὰς</span> <span class=\"greek\">ἀπολιπεῖν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οἰκείων</span> <span class=\"greek\">πράξεων</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">πληρῶσαι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">ἐπαινετοῖς</span> = «as exortações divinas [o povo de Deus] não deixou sem a correspondente prática, antes realizou as palavras mediante obras louváveis»; Jos., Ant. 5, 145; 14, 486).</p><p class=\"entry-text\">ⓐ Do cumprimento de predições ou promessas divinas. Quase sempre no passivo, «ser cumprido» (Polyaenus 1, 18 <span class=\"greek\">τοῦ</span> <span class=\"greek\">λογίου</span> <span class=\"greek\">πεπληρωμένου</span>; Alex. Aphr., Fat. 31, II 2 p. 202, 21 <span class=\"greek\">ὅπως</span> <span class=\"greek\">πληρωθῇ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εἱμαρμένης</span> <span class=\"greek\">δρᾶμα</span>; 3 Km 2:27; TestBenj 3:8 <span class=\"greek\">προφητεία</span>; Ps.-Clem., Hom. 8, 4), referindo-se sobretudo ao Tanakh e suas palavras: <span class=\"greek\">τοῦτο</span> <span class=\"greek\">γέγονεν</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">πληρωθῇ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥηθὲν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προφήτου</span> (cf. 2 Ch 36:21), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:22</a>; cf. 2:15, 17, 23; 4:14; 8:17; 12:17; 13:35; 21:4; 26:54, 56; 27:9 (PNepper-Christensen, D. Mt-evangelium, ’58, 136–62); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:49</a>; 15:27(28) leitura variante (segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:37</a>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:20</a>; 4:21; 21:22 leitura variante; 24:44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:38</a>; 13:18; 15:25; 17:12; 19:24, 36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:16</a> (cf. TestNapht 7:1 <span class=\"greek\">δεῖ</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">πληρωθῆναι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:23</a>. De uma visão: <span class=\"greek\">ἔδει</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> … <span class=\"greek\">ὀπτασίας</span> <span class=\"greek\">πληρωθῆναι</span>, «pois estava destinado a cumprir-se aquilo que [Policarpo] vira em visão», MPol 12:3.—O tipo veterotestamentário encontra cumprimento no antítipo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:16</a> (cf. MBlack, ET 57, ’45/46, 25s., An Aramaic Approach3, ’67, 229–36). Por vezes cumpre-se uma predição de Jesus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:9</a>, 32. Na ativa, «levar ao cumprimento», em parte acerca de Deus, que realiza as profecias divinas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:18</a>; MPol 14:2; em parte acerca de seres humanos, que, pelo que fazem, contribuem para a realização das profecias divinas (Vi. Thu. 1, 8 [= OxfT p. xii, 8] <span class=\"greek\">οὗτος</span> <span class=\"greek\">ἐπλήρωσε</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μεμαντευμένα</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:27</a>. O próprio Jesus cumpre seu destino ao morrer, conforme Moisés e Elias, mensageiros de Deus, prenunciam, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:31</a>.—GPt 5:17.</p><p class=\"entry-text\">ⓑ De uma oração (Chariton 8, 1, 9 <span class=\"greek\">πεπληρώκασιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">εὐχάς</span>; Aristaen., Ep. 1, 16, o deus <span class=\"greek\">πεπλήρωκε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">εὐχήν</span> [= oração]; IBM 894, 8, oração atendida): <span class=\"greek\">πληρῶσαί</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αἴτησιν</span>, «atender minha oração», ITr 13:3 (cf. Ps 19:5; TestAbr A 15 p. 96, 4 [Stone p. 40]). De uma ordem ou mandamento (Herodian 3, 11, 4 <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολάς</span>; POxy 1252A, 9 <span class=\"greek\">πλήρωσον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κεκελευσμένον</span>; 1 Macc 2:55; SibOr 3, 246): <span class=\"greek\">πεπλήρωκεν</span> <span class=\"greek\">ἐντολὴν</span> <span class=\"greek\">δικαιοσύνης</span>, Pol 3:3. <span class=\"greek\">νόμον</span> (Ps.-Demetr., Form. Ep. p. 12, 9; cf. Hdt. 1, 199 <span class=\"greek\">ἐκπλῆσαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:8</a>; passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:14</a> (mas ver 3 acima e cf. Aeschyl., Ag. 313). <span class=\"greek\">τὸ</span> <span class=\"greek\">δικαίωμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:4</a>. <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">δικαιοσύνην</span> (cf. 4 Macc 12:14 <span class=\"greek\">πλ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐσέβειαν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:15</a> (ver AFridrichsen: Congr. d’Hist. du Christ. I 1928, 167–77; OEissfeldt, ZNW 61, ’70, 209–15 e <span class=\"greek\">βαπτίζω</span> 2a, fim); passiva, ISm 1:1 (ver <span class=\"greek\">δικαιοσύνη</span> 3b). Também <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">πρέπον</span> <span class=\"greek\">πληρωθῆναι</span> <span class=\"greek\">πάντα</span>, «convém que tudo se cumpra», GEb 18, 40 (cf. APF 3, 1906, 370 II, 7 [séc. II d.C.] <span class=\"greek\">ἕως</span> <span class=\"greek\">ἅπαντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">πεπληρῶσθαι</span>).—De dever ou cargo: <span class=\"greek\">βλέπε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διακονίαν</span> … , <span class=\"greek\">ἵνα</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">πληροῖς</span>, «atenta para teu dever … e cumpre-o», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:17</a> (cf. CIG 2336 <span class=\"greek\">πλ</span>. <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λειτουργίαν</span>; PFlor 382, 40 <span class=\"greek\">πληρῶσαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">λειτουργίαν</span>; ISardRobert I p. 39 nº 5).—Em emprego absoluto, no sentido mais amplo e em contraste com <span class=\"greek\">καταλύειν</span> (ver <span class=\"greek\">καταλύω</span> 3a): <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἦλθον</span> <span class=\"greek\">καταλῦσαι</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">πληρῶσαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:17</a>; segundo a interpretação do contexto, <span class=\"greek\">πληρόω</span> pode significar aqui «cumprir = fazer, executar», ou «levar à plena expressão = manifestar seu verdadeiro sentido», ou «preencher = completar» (ver AKlöpper, ZWT 39, 1896, 1ss.; AHarnack, Aus Wissenschaft u. Leben II 1911, 225ss., SBBerlAk 1912, 184ss.; JHänel, Der Schriftbegriff Jesu 1919, 155ss.; Dalman, Jesus 56–66 confirma; WHatch, ATR 18, ’36, 129–40; HLjungman, D. Gesetz Erfüllen, ’54; WKümmel, Verheissung u. Erfüllung3, ’56; JO’Rourke, The Fulfilment Texts in Mt, CBQ 24, ’62, 394–403).</p><p class=\"entry-text\">⑤ Levar à conclusão uma atividade de que se participou desde o começo, completar, terminar (1 Macc 4:19): <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:1</a> (cf. TestBenj 12:1 <span class=\"greek\">τοὺ</span> <span class=\"greek\">λόγου</span>). <span class=\"greek\">τὴν</span> <span class=\"greek\">διακονίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:25</a>. [<span class=\"greek\">τὰς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">οἰκο</span>]<span class=\"greek\">νομίας</span> <span class=\"greek\">πληρῶσε</span> (= <span class=\"greek\">πληρῶσαι</span>), «levar até o fim os desígnios de Deus» (isto é, a vida de Paulo, programada por Deus, está prestes a concluir-se), AcPl Ha 5, 27; cf. a restituição em 6, 26 <span class=\"greek\">ο̣ἰ̣κο̣ν̣</span>[<span class=\"greek\">ομίαν</span> <span class=\"greek\">πληρώσω</span>] (cf. a descrição da morte de Jeremias, ParJer 9:31 <span class=\"greek\">ἐπληρώθη</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">οἰκονομία</span>); <span class=\"greek\">τὸν</span> <span class=\"greek\">δρόμον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:25</a>; cf. o emprego absoluto <span class=\"greek\">ἕως</span> <span class=\"greek\">πληρώσωσιν</span>, «até que completem [seu percurso]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:11</a> leitura variante (ver 6 abaixo). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:26</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐχήν</span>, MPol 15:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">κυνηγέσια</span>, 12:2 (outra possibilidade aqui é o sentido intransitivo bastante raro [Hdt. 2, 7 e outros]: «estar concluído, chegar ao fim»). Passivo: «ser realizado, concluído, terminado» (Ps.-Callisth. 1, 24, 9, frase de Filipe moribundo: <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πεπρωμένον</span> <span class=\"greek\">πεπλήρωται</span> = «meu destino se cumpriu»; Mel., P. 43, 297 <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">ἐπληρώθη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐαγγελίου</span> <span class=\"greek\">φωτισθέτος</span>): <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐπληρώθη</span> <span class=\"greek\">ταῦτα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:21</a>. <span class=\"greek\">ἄχρι</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">πληρωθῶσιν</span> <span class=\"greek\">καιροὶ</span> <span class=\"greek\">ἐθνῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:24</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">ἀποκαλύψεις</span> <span class=\"greek\">αὗται</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἔχουσιν</span>· <span class=\"greek\">πεπληρωμέναι</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">εἰσιν</span>, «estas revelações alcançaram seu objetivo, pois estão completas», Hv 3, 3, 2.</p><p class=\"entry-text\">⑥ Completar um número; na passiva, «ter seu número completado» (desde Hdt. 7, 29; Iren. 1, 16, 2 [Harv. I 161, 6]; Hippol., Ref. 6, 51, 2): <span class=\"greek\">ἕως</span> <span class=\"greek\">πληρωθῶσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">σύνδουλοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:11</a> (ver 5 acima).—CMoule, Fulfilment Words in the NT, NTS 14, ’68, 293–320. DELG s.v. <span class=\"greek\">πίμπλημι</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλήρωμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλήρωμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πληρόω</span>; Eur., Hdt. e outros; inscrições, papiros, LXX, Philo; Mel., P. 40, 279).</p><p class=\"entry-text\">① Aquilo que enche.</p><p class=\"entry-text\">ⓐ Aquilo que enche (ou preenche) (Eur., Ion 1051 <span class=\"greek\">κρατήρων</span> <span class=\"greek\">πληρώματα</span>; Hippocr., Aër. 7 <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γαστρός</span>; sobretudo frequentemente da tripulação ou carga de navios desde Thu. 7, 12, 3; 14, 1): <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">αὐτῆς</span>, «a terra e tudo quanto nela existe», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:26</a>; 1 Cl 54:3 (ambos Ps 23:1; também Did., Gen. 74, 8). <span class=\"greek\">ἦραν</span> <span class=\"greek\">κλάσματα</span> <span class=\"greek\">δώδεκα</span> <span class=\"greek\">κοφίνων</span> <span class=\"greek\">πληρώματα</span>, «recolheram pedaços suficientes para encher doze cestos, doze cestos cheios de pedaços», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:43</a>; cf. 8:20 (ver Eccl 4:6; EBishop, ET 60, ’48, 192s.).</p><p class=\"entry-text\">ⓑ Aquilo que torna algo cheio ou completo, suplemento, complemento (Appian, Mithr. 47 §185 <span class=\"greek\">τὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">γυναικῶν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δισχιλίων</span> <span class=\"greek\">ταλάντων</span> <span class=\"greek\">συνέφερον</span>), literalmente do remendo numa roupa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:21</a> (FSynge, ET 56, ’44/45, 26s.).—Figuradamente, talvez da igreja que, como corpo, é <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>., «complemento» de Cristo, a cabeça, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:23</a> (assim Chrysostom.; a palavra poderia ser entendida num sentido análogo em Pla., Rep. 2, 371e <span class=\"greek\">πλ</span>. <span class=\"greek\">πόλεώς</span> <span class=\"greek\">εἰσι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μισθωτοί</span>). Muito mais provavelmente a passagem de Eph pertence a:</p><p class=\"entry-text\">② Aquilo que está cheio de algo (Lucian, Ver. Hist. 2, 37; 38 e Polyaenus 3, 9, 55, o próprio navio tripulado e carregado [ver 1a acima]; Philo, Praem. 65 <span class=\"greek\">γενομένη</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">ἀρετῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχὴ</span> … <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῇ</span> <span class=\"greek\">καταλιποῦσα</span> <span class=\"greek\">κενόν</span>; Herm. Wr. 12, 15, Deus chamado <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span>; 6, 4 <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">πλήρωμά</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κακίας</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγαθοῦ</span>; 16, 3 <span class=\"greek\">τ</span>. <span class=\"greek\">πάντων</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">ἐστι</span>.—Rtzst., Poim. 25, 1): «aquilo que está cheio daquele que» etc. (assim já Severianus de Gabala [KStaab, Pls-Kommentare ’33, 307] e Theodoret, que entendem ser Deus quem enche a igreja.—Cf. CMitton, ET 59, ’47/48, 325; 60, ’48/49, 320s.; CMoule, ibid. 53 e Col and Phil ’57, 164–69).</p><p class=\"entry-text\">③ Aquilo que é levado à plenitude ou conclusão.</p><p class=\"entry-text\">ⓐ Número completo (Hdt. 8, 43; 45, de navios; Aristot., Pol. 2, 7, 22, de cidadãos; Iren. 1, 1, 3 [Harv. I 11, 11] e Hippol., Ref. 6, 38, 4 como termo técnico gnóstico): <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:25</a> (cf. Ael. Aristid. 13 p. 262 D.: <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">ἔθνους</span>). Sobre 11:12, também classificado aqui por muitos, ver 4 abaixo.</p><p class=\"entry-text\">ⓑ Soma total, plenitude, até (super)abundância (Diod S 2, 12, 2 <span class=\"greek\">καθάπερ</span> <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> <span class=\"greek\">πηγῆς</span> <span class=\"greek\">μεγάλης</span> <span class=\"greek\">ἀκέραιον</span> <span class=\"greek\">διαμένει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span> = «como se a abundância [de betume] permanecesse intacta, oriunda de grande fonte»; como termo técnico gnóstico, Iren. 1, 8, 4 [Harv. I, 73, 3]; Hippol., Ref. 8, 10, 3—ver também a): <span class=\"greek\">τινός</span>, «de algo»; <span class=\"greek\">πλ</span>. <span class=\"greek\">εὐλογίας</span> <span class=\"greek\">Χριστοῦ</span>, «plenitude da bênção de Cristo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:29</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">θεότητος</span>, «a plena medida da divindade» (ver <span class=\"greek\">θεότης</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:9</a>; sem genitivo, porém no mesmo sentido, 1:19.—Com genitivo indicando aquele que possui a plenitude: <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">πλ</span>., IEph inscrição (ver comentário ad loc.). <span class=\"greek\">εἰς</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «para que sejais cheios de toda a plenitude de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:19</a> (ver <span class=\"greek\">πληρόω</span> 1b). De Cristo: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πληρώματος</span> <span class=\"greek\">αὐτοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:16</a> (ver Bultmann 51, 7).—Em emprego absoluto: <span class=\"greek\">ἀσπάζομαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πληρώματι</span>, «saúdo na plenitude do espírito cristão», ITr inscrição.—Sobre <span class=\"greek\">εἰς</span> <span class=\"greek\">μέτρον</span> <span class=\"greek\">ἡλικίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πληρώματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:13</a>, ver <span class=\"greek\">μέτρον</span> 2b.</p><p class=\"entry-text\">④ Ato de satisfazer exigências, cumprir, cumprimento (= <span class=\"greek\">πλήρωσις</span>, como Eur., Tro. 824; Philo, Abr. 268 <span class=\"greek\">π</span>. <span class=\"greek\">ἐλπίδων</span>): <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">αὐτῶν</span>, «o cumprimento [da exigência divina] por eles [povo de Israel]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:12</a> (oposto a <span class=\"greek\">παράπτωμα</span> e <span class=\"greek\">ἥττημα</span>). Muitos, porém, consideram que essa passagem pertence a 3a acima. <span class=\"greek\">πλ</span>. <span class=\"greek\">νόμου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span>, «o amor é o cumprimento da lei», 13:10 (sobre o campo semântico do amor, ver TSöding, ETL 68, ’92, 284–330, e Das Liebesgebot bei Paulus ’95).</p><p class=\"entry-text\">⑤ Estado de estar completo, plenitude do tempo (<span class=\"greek\">πληρόω</span> 2): <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χρόνου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:4</a> (ver ASP VI, 587, 34 [24/25 d.C.] <span class=\"greek\">τοῦ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">χρόνου</span> <span class=\"greek\">πληροθέντος</span>); <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">καιρῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:10</a>.—Lghtf., Col and Phlm 255–71; ARobinson, Eph 1904, 255ss.; HMaVallisoleto, Christi ‘Pleroma’ iuxta Pli conceptionem: Verbum Domini 14, ’34, 49–55; FMontgomery-Hitchcock, The Pleroma of Christ: CQR 125, ’37, 1–18; JGewiess: MMeinertz Festschr. ’51, 128–41; PBenoit, RB 63, ’56, 5–44 (epístolas da prisão); AFeuillet, Nouvelle Revue Theol. (Tournai) 88, ’56, 449–72; 593–610 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:23</a>); GMünderlein, NTS 8, ’62, 264–76 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:19</a>); HSchlier, D. Brief an die Epheser4, ’63, 96–99; POverfield, NTS 25, ’79, 384–96; CEvans, Biblica 65, ’84, 259–65 (Nag Hammadi).—DELG s.v. <span class=\"greek\">πίμπλημι</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλήσας, πλησθείς, πλησθῆναι</h1><div class=\"entry-meta\"><span>remissão gramatical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλήσας</span>, <span class=\"greek\">πλησθείς</span>, <span class=\"greek\">πλησθῆναι</span>: ver <span class=\"greek\">πίμπλημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλησίον</h1><div class=\"entry-meta\"><span>advérbio; substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλησίον</span> (formalmente neutro de <span class=\"greek\">πλησίος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span>, adjetivo que remonta a Hom.; Schwyzer I 461), advérbio (Hom.+).</p><p class=\"entry-text\">① Marcador de posição muito próxima de outra, perto, próximo, nas proximidades.</p><p class=\"entry-text\">ⓐ Em emprego absoluto (Diod S 11, 4, 1 <span class=\"greek\">πλησίον</span> <span class=\"greek\">εἶναι</span>; Dionys. Byz. §102; SIG 344, 83; 888, 127; Mitt-Wilck. I/2, 11, 6 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πλ</span>[<span class=\"greek\">ησίο</span>]<span class=\"greek\">ν</span> <span class=\"greek\">κωμῶν</span>; 2 Macc 6:11; Ath. 35, 2 <span class=\"greek\">πλ</span>. <span class=\"greek\">εἶναι</span>): <span class=\"greek\">πλ</span>. <span class=\"greek\">ἑκάτερον</span> <span class=\"greek\">πεφύτευται</span>, «foram plantados perto um do outro», Dg 12:4.</p><p class=\"entry-text\">ⓑ Funciona como preposição com genitivo (Hom.+; Schwyzer II 548): perto de, próximo de algo; <span class=\"greek\">πλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">χωρίου</span> (Menand., Epitr. 242 <span class=\"greek\">πλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">χωρίων</span> S. [=66 Kö.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:5</a>. <span class=\"greek\">πλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">τόπου</span> <span class=\"greek\">ἐκείνου</span>, ApcPt 11:26. <span class=\"greek\">πλ</span>. <span class=\"greek\">ἐκείνων</span>, 13:28.</p><p class=\"entry-text\">② Como substantivo, <span class=\"greek\">ὁ</span> <span class=\"greek\">πλησίον</span>: aquele que está próximo, vizinho, semelhante, outro ser humano (Theognis e outros; X., Mem. 3, 14, 4; Pla., Theaet. 174b <span class=\"greek\">ὁ</span> <span class=\"greek\">πλησίον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">γείτων</span>; Polyb. 12, 25, 5; Plut., Mor. 40c; 57d; Ael. Aristid. 23, 28 K.=42 p. 777 D. e outros; Epict. 4, 13, 2; 9; M. Ant. 4:18 e outros; Ps.-Lucian, Philopatr. 16 <span class=\"greek\">ἐὰν</span> <span class=\"greek\">κτάνῃς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πλησίον</span>, <span class=\"greek\">θανατωθήσῃ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δίκης</span>; LXX; En 99:15; PsSol 8:10; TestIss 5:1s.; Philo, Virt. 116; Jos., Bell. 7, 260; Just., Tat.; Schwyzer II 547), com ou sem genitivo; de um compatriota, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:27</a> (cf. Ex 2:13). De irmãos na fé cristã: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:25</a> (Zech 8:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:12</a>; 1 Cl 38:1; Dg 10:6; IMg 6:2; ITr 8:2; Pol 3:3. No ensino dos Dois Caminhos: B 19:3, B 5s., B 8; D 1:2 (cf. Lev 19:18); 2:3 (cf. Ex 20:17), v. 6. Bastante frequentemente como citação do AT ou em estreita ligação com ele: B 2:8 (Zech 8:17). Sobretudo com frequência, a passagem envolvida é Lev 19:18 (Philosoph. Max., FPhGr I, 489, 27 adverte contra <span class=\"greek\">λυπεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πλησίον</span>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:43</a> (o NT introduz aqui o contraste <span class=\"greek\">ὁ</span> <span class=\"greek\">πλησίον</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐχθρός</span>); 19:19; 22:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:31</a>, 33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:9</a>; cf. v. 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:8</a>. Sem artigo, como predicativo (ver B-D-F §266; Rob. 547 e SSol 5:16): <span class=\"greek\">καὶ</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστίν</span> <span class=\"greek\">μου</span> <span class=\"greek\">πλησίον</span>; «e quem é o meu próximo?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:29</a>; cf. v. 36.—Plural, <span class=\"greek\">οἱ</span> <span class=\"greek\">πλησίον</span> (Ar. 10, 8; 15, 4; Ath. 11, 3; Alex. Aphr., An. Mant. p. 162, 19 Br.), de irmãos na fé cristã, 1 Cl 2:6; 51:2; Dg 10:5.—Billerb. I 353–68; Nathanael 34, 1918, 12ss.; JGspann, Die Nächstenliebe im NT: Der Katholik 87, 1907, 376–91; MRade, Der Nächste: Jülicher Festschr. 1927, 70–79; RBultmann, Aimer son prochain: RHPR 10, 1930, 222–41; EFuchs, ThBl 11, ’32, 129–40; HWeinel, D. Nächstenliebe: Arch. f. d. gesamte Psychol. 86, ’33, 247–60; ANikolainen, D. Nächste als rel. Frage im NT ’37 (ver Theol. Fennica 1, ’39, 13–22); HPreisker, D. Ethos des Urchristentums ’49, 68–81; JBowman, ET 59, ’47/48, 151–3; 248s.; ANissen, Gott u. der Nächste im Antiken Judentum, ’74.—B. 867.—DELG s.v. <span class=\"greek\">πέλας</span> IV. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλησμονή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλησμονή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πίμπλημι</span>; Eur., Pla., X. e outros; GVI I, 1946, 3 = New Docs 4 nº 6, 3; Plut., LXX; PsSol 5:17; Philo; Jos., Ant. 11, 34; Just., D. 126, 6), processo de alcançar satisfação completa, saciedade, sobretudo em comida e bebida, mas também em outros tipos de prazer, satisfação, gratificação (Pla., Leg. 837c; cf. Ps.-Clem., Hom. 8, 15 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">πλησμονήν</span>). Em nossa literatura, o vocábulo só aparece em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:23</a>, numa expressão difícil (Theodore of Mops. I 296 Swete): <span class=\"greek\">πρὸς</span> <span class=\"greek\">πλησμονὴν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σαρκός</span>. Os exegetas gregos entenderam-na como «para a satisfação das necessidades físicas». Porém, <span class=\"greek\">σάρξ</span>, conforme o v. 18, certamente deve ser tomado em sentido pejorativo, e <span class=\"greek\">πρός</span> tem força de «contra». Provavelmente a melhor tradução segue a linha da NRSV: «sem valor algum contra a satisfação dos próprios desejos».—BHall, ET 36, 1925, 285; PHedley, ZNW 27, 1928, 211–16; GBornkamm, TLZ 73, ’48, 18.—DELG s.v. <span class=\"greek\">πίμπλημι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλήσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλήσσω</span> imperfeito <span class=\"greek\">ἔπλησσον</span>; futuro, terceira pessoa do singular <span class=\"greek\">πλήξει</span>, 3 Km 14:14 Aq.; primeiro aoristo, terceira pessoa do singular <span class=\"greek\">ἔπληξεν</span>, 1 Km 11, 11 leitura variante; particípio perfeito <span class=\"greek\">πεπληγώς</span> LXX. Passivo: futuro <span class=\"greek\">πληγήσομαι</span> LXX; segundo aoristo <span class=\"greek\">ἐπλήγην</span>; particípio perfeito <span class=\"greek\">πεπληγμένος</span> (3 Macc 2:22 leitura variante; Just., D. 132, 2) (Hom.+), golpear com força, atingir; das chamas de fogo (Lucian, Jupp. Conf. 15, dos relâmpagos): <span class=\"greek\">τινὰ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀφθαλμῶν</span> (<span class=\"greek\">κατά</span> A 1b), ApcPt 11, 26.—Dos «golpes» ou desastres administrados por Deus que sobrevêm a pessoas ou coisas (Ex 9:31s.; Ps 101:5; TestReub 1:7 <span class=\"greek\">ἔπληξέ</span> <span class=\"greek\">με</span> <span class=\"greek\">πληγῇ</span> <span class=\"greek\">μεγάλῃ</span>); na passiva (Diod S 17, 117, 2 <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> <span class=\"greek\">πληγῆς</span> <span class=\"greek\">πεπληγμένος</span>; Ael. Aristid. 13 p. 206 D.: <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πληγείς</span>; EpArist 313 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>; Tat. 16, 3 <span class=\"greek\">λόγῳ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">δυνάμεως</span> <span class=\"greek\">πληττόμενοι</span>), dos corpos celestes, que perdem um terço de sua luz por causa de um golpe, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:12</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοιάριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλοιάριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Aristoph., X.+; Diod S 14, 30, 4; PEdg 39 [=Sb 6745], 3 [253/252 a.C.]; BGU 812, 5; PGen 14, 8; Ostraka II 1051, 4), diminutivo de <span class=\"greek\">πλοῖον</span>; qualquer tipo de embarcação relativamente pequena, barquinho, pequeno navio, barco, bote, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:9</a> (<span class=\"greek\">πλοῖον</span> é usado para o mesmo tipo de embarcação em 4:1; portanto, provavelmente já não era percebido como diminutivo; é claramente o caso em Ael. Aristid. 50, 35 K. = 26 p. 512 D., onde há apenas <span class=\"greek\">πλοιάρια</span> no porto); 4:36 leitura variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:2</a> leitura variante (em lugar de <span class=\"greek\">πλοῖα</span>); <span class=\"greek\">πλοιάριον</span> <span class=\"greek\">ἄλλο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:22</a>; 23 (ver o texto e as leituras variantes, com alternância de <span class=\"greek\">πλοῖα</span> e <span class=\"greek\">πλοιάρια</span>), 24. <span class=\"greek\">οἱ</span> <span class=\"greek\">μαθηταὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πλοιαρίῳ</span> (dativo comitativo-instrumental; ver Kühner-G. I 430ss.; locativo, talvez instrumental: Rob. 520s.; 533), 21:8.—Dalman, Arbeit VI 351–56, 363–70.—DELG s.v. <span class=\"greek\">πλέω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοῖον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλοῖον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Aeschyl., Hdt.+; especialmente frequente em períodos posteriores, quando <span class=\"greek\">ναῦς</span> [em nossa literatura, apenas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:41</a>; sobre a distinção, ver Didymus p. 321 MSchmidt] se tornou raro; inscrições, papiros, LXX; En 101:4; OdeSol 11:9; TestSol; TestJob 18:7; TestNapht 6:2, 3, 5; EpArist 214; Joseph.—Primariamente, «navio» de qualquer tipo, embora especialmente embarcação mercante).</p><p class=\"entry-text\">① Embarcação marítima relativamente grande, navio: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:13</a>, 38; 21:2s., 6; 27:2–44 (sobre v. 44, ver FZorell, BZ 9, 1911, 159s.); 28:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:9</a>; 18:19.</p><p class=\"entry-text\">② Embarcação pesqueira relativamente pequena, como as usadas no lago de Genesaré, barco (Jos., Vi. 163; 165): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:21</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:19</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:2</a>s., 7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:19</a>, 21ab, 23; com <span class=\"greek\">ἐμβαίνω</span>, sem artigo: <span class=\"greek\">ἐμβαίνειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πλ</span>., «entrar num barco», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:1</a>; 13:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:22</a>, 37 (estas últimas cinco referências apresentam <span class=\"greek\">τό</span> como leitura variante: ver N. e Tdf.); com <span class=\"greek\">ἐμβαίνω</span>, com artigo: <span class=\"greek\">ἐμβαίνειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:22</a> (leitura variante sem <span class=\"greek\">τό</span>); 15:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:18</a>; 8:10 (leitura variante sem <span class=\"greek\">τό</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:3</a>; <span class=\"greek\">ἀναβαίνειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:6</a>. <span class=\"greek\">συνεισέρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:22</a>. <span class=\"greek\">ἐξέρχεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλ</span>., «sair do barco», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.54\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:54</a>. <span class=\"greek\">κατάγειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> (ver <span class=\"greek\">κατάγω</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:11</a>.—Sobre o «barco da Galileia», de dois mil anos, descoberto em 1986, ver OEANE II 377–79.</p><p class=\"entry-text\">③ Em sentido bastante geral, navio: <span class=\"greek\">ὀθόνη</span> <span class=\"greek\">πλοίου</span>, «vela de um navio», MPol 15:2.—EHilgert, The Ship and Related Symbols in the NT, ’60.—B. 727; 729. DELG s.v. <span class=\"greek\">πλέω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλόκαμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλόκαμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πλέκω</span>; Hom. e outros; também Tat. 10, 1 <span class=\"greek\">ὁ</span> <span class=\"greek\">Βερενίκης</span> <span class=\"greek\">πλόκαμος</span>), trança/mecha de cabelo, predominantemente de mulheres (assim no plural desde Il. 14, 176; também 3 Macc 1:4), ApcPt 9:24.—DELG s.v. <span class=\"greek\">πλέκω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0289-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλοκή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλοκή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πλέκω</span>; Eur., Pla. e outros; papiros; Ex 28:14; TestSol 21, 3 Q; EpArist), estado do que está trançado, ato de trançar, trançado, trança: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔξωθεν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πλοκῆς</span> (<span class=\"greek\">ἐκπλοκῆς</span>?) <span class=\"greek\">τριχῶν</span> <span class=\"greek\">κόσμος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:3</a>, leitura variante (em lugar de <span class=\"greek\">ἔξωθεν</span> <span class=\"greek\">ἐμπλοκῆς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κ</span>.).—DELG s.v. <span class=\"greek\">πλέκω</span>.</p></section></article>"};
